          zAxis={[
            {
              id: 'internet-usage',
              colorMap: {
                type: 'continuous',
                min: 0,
                max: 100,
                color: ['#e3f2fd', '#0d47a1'],
              },
            },
          ]}
        >
          <ChartsSurface>
            <GeoDataPlot fill="#f5f5f5" stroke="#bdbdbd" />
            <MapShapePlot />
          </ChartsSurface>
          <ChartsTooltip trigger="item" />
        </ChartsGeoDataProviderPremium>
      </Box>
    </Stack>
  );
}

